/**
 * Fixture-integrity guard for `__tests__/fixtures/crop-repro/crop-repro.zip`
 * (regenerated by its generate.mjs). It's a manual repro fixture for profile-image
 * crop bugs, so nothing else imports it — this test keeps it from silently rotting:
 * it must always parse to 5 people, 5 primary photos, each with the DISTINCT focal
 * crop it advertises. If `generate.mjs` ever breaks the `_FOCAL` encoding or the
 * zip goes stale, CI fails here instead of the fixture quietly reproducing nothing.
 */
import { describe, it, expect } from 'vitest';
import { readFileSync } from 'fs';
import { fileURLToPath } from 'url';
import JSZip from 'jszip';
import { parseGedcom } from '@/lib/gedcom/parser';

const ZIP = fileURLToPath(new URL('../fixtures/crop-repro/crop-repro.zip', import.meta.url));

// The focal crops generate.mjs assigns — spread to the corners + centre so a
// person→person switch shows an unmistakably different crop each time.
const EXPECTED_FOCAL: Record<string, [number, number]> = {
  Ada: [25, 25], Boris: [75, 25], Cleo: [50, 50], Dane: [25, 75], Elsa: [75, 75],
};
const EXPECTED_RADIUS = 30;

describe('crop-repro fixture', () => {
  it('parses to 5 people, each with one primary photo at its own distinct focal crop', async () => {
    const zip = await JSZip.loadAsync(readFileSync(ZIP));
    const ged = await zip.file('family_tree.ged')!.async('string');
    const { people } = parseGedcom(ged);

    expect(people).toHaveLength(5);

    let photos = 0;
    for (const p of people) {
      const expected = EXPECTED_FOCAL[p.FirstName ?? ''];
      expect(expected, `unexpected person "${p.FirstName}"`).toBeDefined();
      expect(p.media).toHaveLength(1);
      const m = p.media[0];
      photos++;
      expect(m.legacyPrimary).toBe(1);
      expect([m.FocalX, m.FocalY]).toEqual(expected);
      expect(m.FocalRadius).toBe(EXPECTED_RADIUS);
    }
    expect(photos).toBe(5);

    // The whole point of the fixture: every crop is different.
    const distinctCrops = new Set(people.map((p) => `${p.media[0].FocalX},${p.media[0].FocalY}`));
    expect(distinctCrops.size).toBe(5);

    // Media files referenced by the GEDCOM must exist in the zip's media/ folder.
    for (let i = 1; i <= 5; i++) {
      expect(zip.file(`media/p${i}.jpg`), `missing media/p${i}.jpg`).not.toBeNull();
    }
  });
});
